// Existing posts, read from the live sitemap, so the ideas never repeat them.
const xml = String($json.data ?? '');
const urls = [...xml.matchAll(/<loc>([^<]+\/blog\/[^<]+\/)<\/loc>/g)].map((m) => m[1]);
const existing = {
  'Portugal (pt-PT)': urls.filter((u) => !u.includes('/br/') && !u.includes('/us/')),
  'Brasil — Curitiba (pt-BR)': urls.filter((u) => u.includes('/br/')),
  'EUA (en-US)': urls.filter((u) => u.includes('/us/')),
};

const prompt = `You are the SEO and content strategist for RUPE, a web design studio.

THE OFFER (same in every market): custom websites, landing pages and online stores, live in 2 days, and the client only pays if they like the result. Optional monthly maintenance covers SEO, local SEO (Google Business Profile), GEO (getting cited by ChatGPT, Gemini, Perplexity and Google AI answers), structured data, speed and blog content.

MARKETS AND PRICES
- Portugal, written in European Portuguese (AO90): landing page 199 €, business website 349 €, online store 499 €. Main market.
- Brasil, Brazilian Portuguese, local focus on Curitiba and the Curitiba metropolitan area: R$ 400 / R$ 700 / R$ 1.000.
- United States, American English: $300 / $525 / $750.

POSTS ALREADY PUBLISHED (do not repeat these topics):
${JSON.stringify(existing, null, 2)}

TASK: propose 5 new blog post ideas for EACH market (15 total). Each idea must target a real search that a small business owner who might hire RUPE would type. Mix: price and comparison guides, local searches (cities and neighbourhoods in that market), practical how-tos, questions people ask AI assistants, and seasonal topics for the next 4–8 weeks. Prefer topics where RUPE's offer is the natural answer. Write every field in the language of its market.

Return ONLY valid JSON, no prose, in exactly this shape:
{"ideas":[{"market":"Portugal|Brasil|EUA","title":"post title, max 65 characters","keyword":"main search query","intent":"commercial|informational|local","why":"one sentence on why this brings clients","outline":["H2 1","H2 2","H2 3","H2 4"],"slug":"url-slug"}]}`;

return [{ json: { prompt } }];

// Claude's reply → one readable email, grouped by market.
const text = ($json.content ?? []).map((part) => part.text ?? '').join('');
let ideas = [];
try {
  ideas = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1)).ideas ?? [];
} catch (error) {
  return [{ json: { subject: 'Ideias do blog — a resposta não veio em JSON', html: `<pre>${text.replace(/</g, '&lt;')}</pre>` } }];
}

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const paths = { Portugal: 'content/blog/pt-PT/', Brasil: 'content/blog/pt-BR/', EUA: 'content/blog/en-US/' };
const groups = ['Portugal', 'Brasil', 'EUA'];

const html = `<div style="font-family:-apple-system,Segoe UI,sans-serif;color:#111;line-height:1.5">
<h2 style="margin:0 0 4px">Ideias para o blog desta semana</h2>
<p style="color:#666;margin:0 0 20px">Para publicar: crie o ficheiro <code>slug.md</code> na pasta indicada, com o título e a descrição no topo, e faça deploy.</p>
${groups
  .map((g) => {
    const list = ideas.filter((i) => i.market === g);
    if (!list.length) return '';
    return `<h3 style="margin:24px 0 8px">${g} <span style="color:#888;font-weight:400">· ${paths[g]}</span></h3>${list
      .map(
        (i) => `<div style="margin:0 0 16px;padding:12px 14px;border:1px solid #e5e2ee;border-radius:10px">
<b>${esc(i.title)}</b><br>
<span style="color:#5b23b8">${esc(i.keyword)}</span> · ${esc(i.intent)} · <code>${esc(i.slug)}.md</code><br>
<span style="color:#555">${esc(i.why)}</span>
<ul style="margin:6px 0 0">${(i.outline ?? []).map((h) => `<li>${esc(h)}</li>`).join('')}</ul></div>`,
      )
      .join('')}`;
  })
  .join('')}
</div>`;

return [{ json: { subject: `Ideias para o blog · ${new Date().toISOString().slice(0, 10)}`, html } }];
